import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { after, before, describe, it } from "node:test";
import { runInNewContext } from "node:vm";
import { ROOT, startServer, type Running } from "./helpers/server.ts";

interface Task {
  id: number;
  title: string;
}

interface ApiError {
  error: { code: string; message: string };
}

function post(server: Running, body: unknown): Promise<Response> {
  return fetch(`${server.baseUrl}/api/tasks`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
}

async function listTasks(server: Running): Promise<Task[]> {
  const body = (await (await fetch(`${server.baseUrl}/api/tasks`)).json()) as { tasks: Task[] };
  return body.tasks;
}

async function assertRejected(server: Running, body: unknown, message: string) {
  const before = await listTasks(server);
  const response = await post(server, body);
  assert.equal(response.status, 400);
  const { error } = (await response.json()) as ApiError;
  assert.equal(error.code, "validation_failed");
  assert.equal(error.message, message);
  assert.deepEqual(await listTasks(server), before, "nothing was stored");
}

describe("SL-004 reject empty and over-long titles", () => {
  describe("API", () => {
    let server: Running;

    before(async () => {
      server = await startServer();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: an empty title answers 400 validation_failed and stores nothing", async () => {
      await assertRejected(server, { title: "" }, "A title is required.");
    });

    it("AC-1: a title of only spaces is rejected like an empty one", async () => {
      await assertRejected(server, { title: "     " }, "A title is required.");
    });

    it("AC-1: a title of only tabs and newlines is rejected", async () => {
      await assertRejected(server, { title: "\t\n " }, "A title is required.");
    });

    it("AC-1: a missing or non-string title is rejected, not a crash", async () => {
      await assertRejected(server, {}, "Title must be a string.");
      await assertRejected(server, { title: 42 }, "Title must be a string.");
      await assertRejected(server, { title: null }, "Title must be a string.");
    });

    it("AC-2: a 501-character title answers 400 validation_failed and stores nothing", async () => {
      await assertRejected(
        server,
        { title: "a".repeat(501) },
        "The title is too long (maximum 500 characters).",
      );
    });

    it("AC-2: the limit counts the trimmed title, so 500 characters plus spaces is accepted", async () => {
      const title = "b".repeat(500);
      const response = await post(server, { title: `  ${title}  ` });
      assert.equal(response.status, 201);
      const { task } = (await response.json()) as { task: Task };
      assert.equal(task.title, title);
    });

    it("AC-2: a title that is 501 characters only because of spaces is still too long only if trimmed length is over 500", async () => {
      await assertRejected(
        server,
        { title: ` ${"c".repeat(501)} ` },
        "The title is too long (maximum 500 characters).",
      );
    });

    it("AC-1: a rejected request does not stop valid titles being created afterwards", async () => {
      const response = await post(server, { title: "Still works" });
      assert.equal(response.status, 201);
    });
  });

  describe("page", () => {
    let server: Running;
    let html: string;

    before(async () => {
      server = await startServer();
      html = await (await fetch(`${server.baseUrl}/`)).text();
    });
    after(async () => {
      await server?.stop();
    });

    it("AC-1: has an alert element with id form-message for the reason", () => {
      assert.match(html, /<[a-z]+(?=[^>]*id=["']form-message["'])(?=[^>]*role=["']alert["'])/);
    });

    /** Runs public/app.js against a minimal fake page and a scripted fetch. */
    async function submitWith(response: { status: number; body: unknown }, title: string) {
      const elements: Record<string, any> = {
        "task-form": {
          handler: undefined as undefined | ((e: unknown) => Promise<void>),
          addEventListener(_: string, fn: (e: unknown) => Promise<void>) {
            this.handler = fn;
          },
        },
        "task-title": { value: title },
        "task-list": { replaceChildren() {} },
        "form-message": { textContent: "stale" },
        "empty-state": { hidden: false },
      };
      const calls: string[] = [];
      const fakeFetch = async (url: string, init?: { method?: string }) => {
        calls.push(`${init?.method ?? "GET"} ${url}`);
        if (init?.method === "POST") {
          return { ok: response.status < 400, status: response.status, json: async () => response.body };
        }
        return { ok: true, status: 200, json: async () => ({ tasks: [] }) };
      };
      runInNewContext(readFileSync(join(ROOT, "public", "app.js"), "utf8"), {
        document: {
          getElementById: (id: string) => elements[id],
          createElement: () => ({}),
        },
        fetch: fakeFetch,
      });
      await new Promise((resolve) => setImmediate(resolve));
      await elements["task-form"].handler({ preventDefault() {} });
      return { elements, calls };
    }

    it("AC-1: shows the server's message and keeps the typed title when the request is rejected", async () => {
      const { elements } = await submitWith(
        { status: 400, body: { error: { code: "validation_failed", message: "A title is required." } } },
        "   ",
      );
      assert.equal(elements["form-message"].textContent, "A title is required.");
      assert.equal(elements["task-title"].value, "   ");
    });

    it("AC-2: shows the too-long message the same way", async () => {
      const message = "The title is too long (maximum 500 characters).";
      const { elements } = await submitWith(
        { status: 400, body: { error: { code: "validation_failed", message } } },
        "a".repeat(501),
      );
      assert.equal(elements["form-message"].textContent, message);
    });

    it("AC-1: clears the message and the field after a successful submit", async () => {
      const { elements } = await submitWith(
        { status: 201, body: { task: { id: 1, title: "Buy milk" } } },
        "Buy milk",
      );
      assert.equal(elements["form-message"].textContent, "");
      assert.equal(elements["task-title"].value, "");
    });
  });
});
